<?php

declare(strict_types=1);

require_once dirname(__DIR__, 2) . '/config.php';
require_once ROOT_PATH . '/database/config/db.php';
require_once ROOT_PATH . '/security/middleware/AuthMiddleware.php';

AuthMiddleware::startSession();
$user = AuthMiddleware::requireAuth();
$csrf = AuthMiddleware::csrfToken();
$serverId = (int)($_GET['server_id'] ?? 0);
$channelId = (int)($_GET['channel_id'] ?? 0);
?>
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Collabs – <?= htmlspecialchars(APP_NAME, ENT_QUOTES, 'UTF-8') ?></title>
<style>
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#0f1117;color:#f5f7fb;font-family:Inter,system-ui,sans-serif}.shell{max-width:1400px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px}.back{color:#aeb8ca;text-decoration:none}.brand h1{margin:7px 0 3px}.muted{color:#98a1b2}.layout{display:grid;grid-template-columns:230px 1fr;gap:18px;margin-top:20px}.panel{background:#171a23;border:1px solid #292e3b;border-radius:16px}.side{padding:15px;height:max-content}.label{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#7f899c;margin:6px 8px}.server{padding:7px 8px 18px;font-weight:700}.nav-item{width:100%;border:0;background:transparent;color:#cbd3e0;text-align:left;padding:11px 12px;border-radius:10px;cursor:pointer;margin:2px 0;font-size:14px}.nav-item:hover,.nav-item.active{background:#252a38;color:#fff}.main{padding:25px}.title{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.title h2{margin:8px 0}.pill{display:inline-flex;align-items:center;padding:5px 9px;border-radius:999px;background:#252a38;color:#cbd3e0;font-size:11px}.green{color:#8ee6a8}.tabs{display:flex;gap:7px;margin:22px 0 15px;flex-wrap:wrap}.tab,.sort{border:1px solid #303646;background:#141720;color:#cbd3e0;border-radius:9px;padding:8px 11px;cursor:pointer}.tab.active{background:#2b3140;color:#fff}.templates{display:flex;gap:12px;overflow:auto;padding-bottom:4px}.template{min-width:130px;border:1px solid #2d3340;background:#141720;border-radius:12px;padding:10px;cursor:pointer}.template:hover{background:#1d2230}.template-thumb{height:72px;border-radius:8px;background:#202534;display:grid;place-items:center;font-size:28px;margin-bottom:9px}.template strong{font-size:12px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:23px 0 13px}.toolbar-right{display:flex;gap:7px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(245px,1fr));gap:15px}.card{border:1px solid #2d3340;background:#141720;border-radius:13px;overflow:hidden;cursor:pointer}.card:hover{border-color:#4b5365;transform:translateY(-1px)}.thumb{height:168px;background:#202534;position:relative;display:grid;place-items:center}.thumb-page{width:76px;height:105px;background:#f7f8fb;color:#303541;border-radius:4px;box-shadow:0 8px 22px #0005;display:flex;align-items:center;justify-content:center;font-size:34px}.live{position:absolute;top:10px;left:10px;background:#e5484d;color:white;border-radius:5px;padding:4px 7px;font-size:10px;font-weight:800}.viewers{position:absolute;bottom:9px;left:9px;background:#0b0d12dd;color:#fff;border-radius:5px;padding:5px 7px;font-size:10px}.card-body{padding:12px}.doc-title{font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.meta{font-size:12px;color:#929caf;margin-top:6px}.avatars{display:flex;gap:5px;margin-top:10px;min-height:24px;align-items:center}.avatar{width:24px;height:24px;border-radius:50%;background:#303747;display:grid;place-items:center;font-size:10px;border:2px solid #141720}.names{font-size:11px;color:#b8c1d0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tag{display:inline-block;margin-top:8px;margin-right:5px;font-size:10px;padding:3px 6px;border-radius:5px;background:#252a38;color:#aeb8ca}.list{display:none}.list .row{display:grid;grid-template-columns:45px 1fr 160px 120px;gap:10px;align-items:center;padding:11px;border-bottom:1px solid #292e3b}.row-icon{font-size:23px}.empty{padding:45px 15px;text-align:center;color:#9aa4b6;border:1px dashed #303646;border-radius:12px}.notice{padding:14px;border-radius:10px;background:#232837;color:#cbd3e0}.new-card{border:1px dashed #4a5264;background:#141720}.new-card .thumb-page{font-size:32px;background:#252a38;color:#d8deea}.loading{padding:30px;text-align:center;color:#9aa4b6}@media(max-width:800px){.layout{grid-template-columns:1fr}.side{display:flex;align-items:center;gap:5px;overflow:auto}.side .label,.server{display:none}.nav-item{width:auto;white-space:nowrap}.main{padding:18px}.list .row{grid-template-columns:38px 1fr 90px}.list .row .hide-small{display:none}}
</style>
<script src="<?= BASE_URL ?>/assets/js/accessibility-apply.js" defer></script>
</head>
<body>
<div class="shell">
<header class="top"><div class="brand"><a class="back" id="backToChat" href="<?= BASE_URL ?>/modules/chat/chat.php">← Back to Chat</a><h1>🤝 Collabs</h1><span class="muted">One shared collaboration space for your selected server.</span></div><span class="pill">👤 <?= htmlspecialchars((string)($user['full_name'] ?: $user['username']), ENT_QUOTES, 'UTF-8') ?></span></header>
<div class="layout">
<aside class="panel side"><div class="label">Server</div><div id="serverName" class="server">Loading…</div><div class="label">Collabs</div><button class="nav-item active" id="documentsNav">📄 Documents</button><button class="nav-item" id="whiteboardNav">🖊 Whiteboard</button></aside>
<main class="panel main" id="detail"><div class="loading">Loading your Coworkspace…</div></main>
</div></div>
<script>
const API='<?= BASE_URL ?>/API/collaboration/server-coworkspaces.php',DOCS='<?= BASE_URL ?>/API/collaboration/documents.php',PRESENCE='<?= BASE_URL ?>/API/collaboration/document-presence.php',CSRF='<?= htmlspecialchars($csrf,ENT_QUOTES,'UTF-8') ?>',SERVER_ID=<?= $serverId ?>,CHANNEL_ID=<?= $channelId ?>,BASE='<?= BASE_URL ?>';
const state={server:null,workspace:null,docs:[],type:'docx',sort:'live',view:'grid',section:'documents'};
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const typeName=t=>t==='xlsx'?'Excel':t==='pptx'?'PowerPoint':'Word';
const icon=t=>t==='xlsx'?'📊':t==='pptx'?'📽':'📄';
async function getJson(url){const r=await fetch(url,{credentials:'same-origin'});const d=await r.json().catch(()=>({error:'Invalid response'}));if(!r.ok||!d.success)throw new Error(d.error||'Request failed');return d}
async function postJson(url,data){const r=await fetch(url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({...data,csrf_token:CSRF})});const d=await r.json().catch(()=>({error:'Invalid response'}));if(!r.ok||!d.success)throw new Error(d.error||'Request failed');return d}
function templates(){const sets={docx:['Blank','Report','Proposal','Letter','Brochure'],xlsx:['Blank','Budget','Tracker','Schedule','Gradebook'],pptx:['Blank','Report','Pitch Deck','Lesson','Project']};return sets[state.type].map((name,i)=>`<button class="template" onclick="createDoc('${esc(name)}')"><div class="template-thumb">${i?'✦': '＋'}</div><strong>${esc(name)}</strong></button>`).join('')}
function sortedDocs(){let docs=state.docs.filter(d=>d.file_type===state.type);if(state.sort==='live')docs.sort((a,b)=>(b.presence.total>0)-(a.presence.total>0)||new Date(b.updated_at)-new Date(a.updated_at));else docs.sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at));return docs}
function card(d){const p=d.presence||{total:0,editing:0,viewing:0,users:[]};const live=p.total>0;const names=p.users.map(x=>x.display_name).slice(0,3).join(', ');return `<article class="card" onclick="openDoc('${esc(d.open_url)}')"><div class="thumb">${live?'<span class="live">🔴 LIVE</span>':''}<span class="viewers">${p.editing?esc(p.editing)+' editing':p.viewing?esc(p.viewing)+' viewing':'No one here'}</span><div class="thumb-page">${icon(d.file_type)}</div></div><div class="card-body"><div class="doc-title">${icon(d.file_type)} ${esc(d.title)}</div><div class="avatars">${p.users.slice(0,3).map(x=>`<span class="avatar">${esc((x.display_name||'?').slice(0,1).toUpperCase())}</span>`).join('')}${names?`<span class="names">${esc(names)}</span>`:'<span class="names">Edited '+timeAgo(d.updated_at)+'</span>'}</div>${live?`<span class="tag">${p.editing?'✏️ '+p.editing+' editing':'👁 '+p.viewing+' viewing'}</span>`:''}</div></article>`}
function listRow(d){const p=d.presence||{total:0,editing:0,viewing:0};return `<div class="row" onclick="openDoc('${esc(d.open_url)}')"><span class="row-icon">${icon(d.file_type)}</span><div><b>${esc(d.title)}</b><div class="meta">${esc(d.file_name)}</div></div><span class="hide-small">${p.total?'🔴 '+p.total+' active':'Edited '+timeAgo(d.updated_at)}</span><span>${p.editing?'✏️ '+p.editing:p.viewing?'👁 '+p.viewing:'—'}</span></div>`}
function timeAgo(value){const sec=Math.max(1,Math.floor((Date.now()-new Date(value).getTime())/1000));if(sec<60)return sec+'s ago';if(sec<3600)return Math.floor(sec/60)+'m ago';if(sec<86400)return Math.floor(sec/3600)+'h ago';return Math.floor(sec/86400)+'d ago'}
function renderDocs(){const docs=sortedDocs();document.getElementById('detail').innerHTML=`<div class="title"><div><span class="pill">📄 DOCUMENTS</span><h2>${esc(state.server.name)} · ${typeName(state.type)}</h2><span class="muted">Create, open and collaborate without leaving this server's Coworkspace.</span></div><span class="pill green">🟢 ${state.docs.reduce((n,d)=>n+(d.presence?.total||0),0)} active</span></div><div class="tabs"><button class="tab ${state.type==='docx'?'active':''}" onclick="setType('docx')">📄 Word</button><button class="tab ${state.type==='xlsx'?'active':''}" onclick="setType('xlsx')">📊 Excel</button><button class="tab ${state.type==='pptx'?'active':''}" onclick="setType('pptx')">📽 PowerPoint</button></div><div class="label" style="margin-left:0">Start a new ${typeName(state.type)} document</div><div class="templates">${templates()}</div><div class="toolbar"><span class="muted">${docs.length} document${docs.length===1?'':'s'}</span><div class="toolbar-right"><button class="sort" onclick="state.sort=state.sort==='live'?'recent':'live';renderDocs()">Sort: ${state.sort==='live'?'🔴 Live first':'Recently active'} ▾</button><button class="sort" onclick="state.view='grid';renderDocs()">⊞</button><button class="sort" onclick="state.view='list';renderDocs()">☰</button></div></div>${docs.length?(state.view==='grid'?`<div class="grid">${docs.map(card).join('')}<article class="card new-card" onclick="createDoc('Blank')"><div class="thumb"><div class="thumb-page">＋</div></div><div class="card-body"><div class="doc-title">New ${typeName(state.type)} document</div><div class="meta">Start from blank</div></div></article></div>`:`<div class="list">${docs.map(listRow).join('')}</div>`):`<div class="empty"><h3>No documents yet</h3><p>Use a template above to create the first ${typeName(state.type)} document.</p></div>`}`}
function renderWhiteboard(){document.getElementById('detail').innerHTML=`<div class="title"><div><span class="pill">🖊 WHITEBOARD</span><h2>${esc(state.server.name)} Whiteboard</h2><span class="muted">Independent from individual Chat channels.</span></div><span class="pill green">Shared server space</span></div><div class="notice" style="margin-top:25px">Whiteboard remains the next Collabs container. Its access is already governed by the server-level Coworkspace; document work in this phase is isolated to the Documents container.</div>`}
function render(){state.section==='documents'?renderDocs():renderWhiteboard()}
function setType(t){state.type=t;state.view='grid';renderDocs()}
function openDoc(url){window.location.href=url}
async function createDoc(template){try{const title=template==='Blank'?'Untitled '+typeName(state.type):template+' — '+state.server.name;const d=await postJson(DOCS,{workspace_id:state.workspace.id,title,type:state.type});window.location.href=d.document.open_url}catch(e){alert(e.message)}}
async function refreshDocs(){try{const d=await getJson(DOCS+'?workspace_id='+encodeURIComponent(state.workspace.id));state.docs=d.documents||[];if(state.section==='documents')renderDocs()}catch(e){console.warn(e)}}
async function boot(){try{const q=SERVER_ID?`?server_id=${SERVER_ID}`:`?channel_id=${CHANNEL_ID}`;const d=await getJson(API+q);state.server=d.server;state.workspace=(d.workspaces||[])[0];if(!state.workspace)throw new Error('The server Coworkspace could not be synchronized.');document.getElementById('serverName').textContent=state.server.name;document.getElementById('backToChat').href=BASE+'/modules/chat/chat.php?server_id='+encodeURIComponent(state.server.id);await refreshDocs()}catch(e){document.getElementById('detail').innerHTML='<div class="notice">'+esc(e.message)+'</div>'}}
document.getElementById('documentsNav').onclick=()=>{state.section='documents';document.getElementById('documentsNav').classList.add('active');document.getElementById('whiteboardNav').classList.remove('active');render()};document.getElementById('whiteboardNav').onclick=()=>{state.section='whiteboard';document.getElementById('whiteboardNav').classList.add('active');document.getElementById('documentsNav').classList.remove('active');render()};boot();setInterval(refreshDocs,10000);
</script>
</body></html>
